diff --git a/plugins/woocommerce/changelog/53136-platform-selector-mobile-keyboard b/plugins/woocommerce/changelog/53136-platform-selector-mobile-keyboard
new file mode 100644
index 0000000000..5035673013
--- /dev/null
+++ b/plugins/woocommerce/changelog/53136-platform-selector-mobile-keyboard
@@ -0,0 +1,4 @@
+Significance: patch
+Type: fix
+
+Stop the virtual keyboard from opening on the core profiler platform selector on touch devices.
diff --git a/plugins/woocommerce/client/admin/client/core-profiler/components/multiple-selector/multiple-selector.tsx b/plugins/woocommerce/client/admin/client/core-profiler/components/multiple-selector/multiple-selector.tsx
index 8012f41931..3e04eb59f7 100644
--- a/plugins/woocommerce/client/admin/client/core-profiler/components/multiple-selector/multiple-selector.tsx
+++ b/plugins/woocommerce/client/admin/client/core-profiler/components/multiple-selector/multiple-selector.tsx
@@ -26,82 +26,86 @@ type Props = {
 export const MultipleSelector = ( {
 	options,
 	onSelect,
 	selectedOptions = [],
 	placeholder = __( 'Select platforms', 'woocommerce' ),
 	onOpenClose = () => {},
 }: Props ) => {
 	return (
 		<SelectControl
 			className="woocommerce-profiler-platform-selector"
 			label=""
 			multiple
 			__experimentalOpenMenuOnFocus
 			readOnlyWhenClosed={ false }
 			items={ options }
 			getFilteredItems={ ( allItems ) => allItems }
 			selected={ selectedOptions }
 			inputProps={ {
+				// Typing is not supported here, and on touch devices the
+				// virtual keyboard covers the menu with no way to dismiss it,
+				// so keep it from opening.
+				readOnly: true,
 				'aria-readonly': true,
 				'aria-label': __(
 					'Use up and down arrow keys to navigate',
 					'woocommerce'
 				),
 			} }
 			onKeyDown={ ( e ) => {
 				if ( e.key.length <= 1 ) {
 					e.preventDefault();
 					return false;
 				}
 			} }
 			placeholder={ selectedOptions.length ? '' : placeholder }
 			stateReducer={ ( state, actionAndChanges ) => {
 				const { changes, type } = actionAndChanges;
 				switch ( type ) {
 					case selectControlStateChangeTypes.ControlledPropUpdatedSelectedItem:
 						return {
 							...changes,
 							inputValue: state.inputValue,
 						};
 					case selectControlStateChangeTypes.ItemClick:
 						return {
 							...changes,
 							isOpen: true,
 							inputValue: state.inputValue,
 							highlightedIndex: state.highlightedIndex,
 						};
 					case selectControlStateChangeTypes.InputBlur:
 						if ( state.isOpen && actionAndChanges.selectItem ) {
 							// Prevent the menu from closing when clicking on a selected item.
 							return {
 								...changes,
 								isOpen: true,
 							};
 						}
 						return changes;
 					default:
 						return changes;
 				}
 			} }
 			onSelect={ ( item ) => {
 				if ( ! item ) {
 					return;
 				}
 				const exist = selectedOptions.find(
 					( existingItem ) => existingItem.value === item.value
 				);
 				const updatedPlatforms = exist
 					? selectedOptions.filter(
 							( existingItem ) =>
 								existingItem.value !== item.value
 					  )
 					: [ ...selectedOptions, item ];
 				onSelect( updatedPlatforms );
 			} }
 			onRemove={ ( item ) =>
 				onSelect( selectedOptions.filter( ( i ) => i !== item ) )
 			}
 		>
 			{ renderMenu( { selectedOptions, onOpenClose } ) }
 		</SelectControl>
 	);
 };
diff --git a/plugins/woocommerce/client/admin/client/core-profiler/pages/test/user-profile.test.tsx b/plugins/woocommerce/client/admin/client/core-profiler/pages/test/user-profile.test.tsx
index fe88836789..86ec82dcc5 100644
--- a/plugins/woocommerce/client/admin/client/core-profiler/pages/test/user-profile.test.tsx
+++ b/plugins/woocommerce/client/admin/client/core-profiler/pages/test/user-profile.test.tsx
@@ -11,119 +11,186 @@ import { UserProfile } from '../UserProfile';
 import { CoreProfilerStateMachineContext } from '../..';

 describe( 'UserProfile', () => {
+	// jsdom does not implement scrollIntoView, which the select control menu
+	// calls when it opens.
+	Object.defineProperty( window.HTMLElement.prototype, 'scrollIntoView', {
+		value: jest.fn(),
+		writable: true,
+	} );
+
 	let props: {
 		sendEvent: jest.Mock;
 		navigationProgress: number;
 		context: Pick< CoreProfilerStateMachineContext, 'userProfile' >;
 	};

 	beforeEach( () => {
 		props = {
 			sendEvent: jest.fn(),
 			navigationProgress: 0,
 			context: {
 				userProfile: {
 					businessChoice: 'im_just_starting_my_business',
 					sellingOnlineAnswer: null,
 					sellingPlatforms: null,
 				},
 			},
 		};
 	} );

 	it( 'should render user profile page', () => {
 		// @ts-ignore
 		render( <UserProfile { ...props } /> );
 		expect(
 			screen.getByText( /Which one of these best describes you?/i, {
 				selector: 'h1',
 			} )
 		).toBeInTheDocument();
 		expect(
 			screen.getByRole( 'button', {
 				name: /Continue/i,
 			} )
 		).toBeInTheDocument();
 	} );

 	it( 'should show online selling question when choosing "im_already_selling"', () => {
 		// @ts-ignore
 		render( <UserProfile { ...props } /> );
 		const radioInput = screen.getByLabelText< HTMLInputElement >(
 			'I’m already selling'
 		); // Replace with the label of your radio button

 		// Perform the radio button selection
 		fireEvent.click( radioInput );

 		// Assert the expected behavior
 		expect( radioInput.checked ).toBe( true );

 		const onlineSellingQuestion = screen.getByText(
 			/Are you selling online?/i
 		);
 		expect( onlineSellingQuestion ).toBeInTheDocument();
 	} );

 	it( 'should show online selling question when choosing "Yes, I’m selling online"', () => {
 		render(
 			// @ts-ignore
 			<UserProfile
 				{ ...{
 					...props,
 					context: {
 						userProfile: {
 							businessChoice: 'im_already_selling',
 							sellingOnlineAnswer: 'yes_im_selling_online',
 							sellingPlatforms: null,
 						},
 					},
 				} }
 			/>
 		);
 		const platformSelector = screen.getByLabelText( /Select an option/i );
 		expect( platformSelector ).toBeInTheDocument();
 	} );

+	it( 'should render the platform selector as read-only so touch devices do not open the keyboard', () => {
+		render(
+			// @ts-ignore
+			<UserProfile
+				{ ...{
+					...props,
+					context: {
+						userProfile: {
+							businessChoice: 'im_already_selling',
+							sellingOnlineAnswer: 'yes_im_selling_online',
+							sellingPlatforms: null,
+						},
+					},
+				} }
+			/>
+		);
+		expect(
+			screen.getByLabelText( /Use up and down arrow keys to navigate/i )
+		).toHaveAttribute( 'readonly' );
+	} );
+
+	it( 'should still allow selecting a platform from the read-only selector', () => {
+		render(
+			// @ts-ignore
+			<UserProfile
+				{ ...{
+					...props,
+					context: {
+						userProfile: {
+							businessChoice: 'im_already_selling',
+							sellingOnlineAnswer: 'yes_im_selling_online',
+							sellingPlatforms: null,
+						},
+					},
+				} }
+			/>
+		);
+
+		fireEvent.focus(
+			screen.getByLabelText( /Use up and down arrow keys to navigate/i )
+		);
+		fireEvent.click( screen.getByText( 'Amazon' ) );
+		screen
+			.getByRole( 'button', {
+				name: /Continue/i,
+			} )
+			.click();
+
+		expect( props.sendEvent ).toHaveBeenCalledWith( {
+			type: 'USER_PROFILE_COMPLETED',
+			payload: {
+				userProfile: {
+					businessChoice: 'im_already_selling',
+					sellingOnlineAnswer: 'yes_im_selling_online',
+					sellingPlatforms: [ 'amazon' ],
+				},
+			},
+		} );
+	} );
+
 	it( 'should call sendEvent with USER_PROFILE_COMPLETED event when button is clicked', () => {
 		render(
 			// @ts-ignore
 			<UserProfile { ...props } />
 		);
 		screen
 			.getByRole( 'button', {
 				name: /Continue/i,
 			} )
 			.click();
 		expect( props.sendEvent ).toHaveBeenCalledWith( {
 			type: 'USER_PROFILE_COMPLETED',
 			payload: {
 				userProfile: {
 					businessChoice: 'im_just_starting_my_business',
 					sellingOnlineAnswer: null,
 					sellingPlatforms: null,
 				},
 			},
 		} );
 	} );

 	it( 'should call sendEvent with USER_PROFILE_SKIPPED event when skip button is clicked', () => {
 		render(
 			// @ts-ignore
 			<UserProfile { ...props } />
 		);
 		screen
 			.getByRole( 'button', {
 				name: /Skip this step/i,
 			} )
 			.click();
 		expect( props.sendEvent ).toHaveBeenCalledWith( {
 			type: 'USER_PROFILE_SKIPPED',
 			payload: {
 				userProfile: {
 					skipped: true,
 				},
 			},
 		} );
 	} );
 } );
